'use strict';

// MODULES //

var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var format = require( '@stdlib/string/format' );
var base = require( './base.js' );


// VARIABLES //

var NORMS = [ 'M', 'm', '1', 'O', 'o', 'I', 'i', 'F', 'f', 'E', 'e' ];
var UPLOS = [ 'upper', 'lower' ];


// MAIN //

/**
* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix `AP` supplied in packed form.
*
* @param {string} order - storage layout of `AP`
* @param {string} norm - specifies the norm type
* @param {string} uplo - specifies whether the upper or lower triangular part of `A` is referenced
* @param {NonNegativeInteger} N - order of the matrix `A`
* @param {Float64Array} AP - packed form of a symmetric matrix `A`
* @throws {TypeError} first argument must be a valid order
* @throws {TypeError} second argument must be a valid norm type
* @throws {TypeError} third argument must be a valid uplo value
* @returns {number} matrix norm
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* // AP = [ 1.0, 2.0, 5.0 ] (2x2 symmetric packed column-major upper)
* var AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );
*
* var norm = dlansp( 'column-major', 'M', 'upper', 2, AP );
* // returns 5.0
*/
function dlansp( order, norm, uplo, N, AP ) {
	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	if ( NORMS.indexOf( norm ) === -1 ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a valid norm type. Value: `%s`.', norm ) );
	}
	if ( UPLOS.indexOf( uplo ) === -1 ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a valid uplo value. Value: `%s`.', uplo ) );
	}
	return base( order, norm, uplo, N, AP, 1, 0 );
}


// EXPORTS //

module.exports = dlansp;
